import { useEffect, useRef, useState, type FC, type ComponentType, type SVGAttributes } from "react";
import {
  CheckIcon,
  VoiceCallSolidIcon,
  VolumeOnSolidIcon,
  HeadphonesSolidIcon,
} from "@vector-im/compound-design-tokens/assets/web/icons";
import { useTranslation } from "react-i18next";

import { LoudspeakerButton } from "../button";
import { type AudioOutputDeviceLabel } from "../state/MediaDevices";
import { useMediaDevices } from "../MediaDevicesContext";
import styles from "./AudioOutputButton.module.css";

export interface AudioOutputMenuOption {
  id: string;
  label: AudioOutputDeviceLabel;
}

export interface AudioOutputButtonProps {
  size?: "md" | "lg";
  loudspeakerModeEnabled: boolean;
  /** The available audio output devices (built-in earpiece/speaker, Bluetooth, wired, …). */
  options: AudioOutputMenuOption[];
  /** The id of the currently selected output device. */
  selectedOption?: string;
  onSelect: (id: string) => void;
}

/**
 * Tapping the speaker/loudspeaker button opens a menu listing every available audio output
 * device (built-in earpiece/speaker, Bluetooth, wired headset, …) to pick from directly —
 * mirroring how most native phone dialers and messaging apps let you switch straight to a
 * connected Bluetooth headset, rather than only toggling between earpiece and loudspeaker.
 *
 * This is a plain, dependency-free popover (no Radix/vaul) rather than reusing compound-web's
 * `Menu`, which on Android renders as a `vaul` swipe-gesture drawer — a code path Element Call
 * had never actually shipped on a touch device (its only prior consumer, the mic/camera
 * switcher, is desktop-only), and which turned out not to reliably deliver item taps in this
 * app's WebView. Plain buttons with native click handling avoid that risk entirely.
 */
export const AudioOutputButton: FC<AudioOutputButtonProps> = ({
  size,
  loudspeakerModeEnabled,
  options,
  selectedOption,
  onSelect,
}) => {
  const [open, setOpen] = useState(false);
  const { t } = useTranslation();
  const devices = useMediaDevices();
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (open) devices.requestDeviceNames();
  }, [open, devices]);

  // Close the menu when tapping anywhere outside it.
  useEffect(() => {
    if (!open) return;
    const onPointerDown = (e: PointerEvent): void => {
      if (
        containerRef.current &&
        !containerRef.current.contains(e.target as Node)
      ) {
        setOpen(false);
      }
    };
    document.addEventListener("pointerdown", onPointerDown, true);
    return () =>
      document.removeEventListener("pointerdown", onPointerDown, true);
  }, [open]);

  return (
    <div className={styles.container} ref={containerRef}>
      {open && (
        <div className={styles.menu} role="menu">
          {options.map(({ id, label }) => {
            let labelText: string;
            let Icon: ComponentType<SVGAttributes<SVGElement>>;
            switch (label.type) {
              case "earpiece":
                labelText = t("settings.devices.handset");
                Icon = VoiceCallSolidIcon;
                break;
              case "speaker":
                labelText = t("settings.devices.loudspeaker");
                Icon = VolumeOnSolidIcon;
                break;
              case "default":
                labelText = label.name ?? t("common.audio");
                Icon = HeadphonesSolidIcon;
                break;
              case "number":
                labelText = t("settings.devices.speaker_numbered", {
                  n: label.number,
                });
                Icon = HeadphonesSolidIcon;
                break;
              case "name":
                labelText = label.name;
                Icon = HeadphonesSolidIcon;
                break;
            }
            return (
              <button
                key={id}
                type="button"
                role="menuitemradio"
                aria-checked={selectedOption === id}
                className={styles.item}
                onClick={() => {
                  setOpen(false);
                  if (id === selectedOption) return;
                  onSelect(id);
                }}
              >
                <Icon
                  width={20}
                  height={20}
                  className={styles.itemIcon}
                  aria-hidden
                />
                <span className={styles.itemLabel}>{labelText}</span>
                {selectedOption === id && (
                  <CheckIcon
                    width={20}
                    height={20}
                    className={styles.itemCheck}
                    aria-hidden
                  />
                )}
              </button>
            );
          })}
        </div>
      )}
      <LoudspeakerButton
        size={size}
        loudspeakerModeEnabled={loudspeakerModeEnabled}
        onClick={() => setOpen((o) => !o)}
      />
    </div>
  );
};
