import { useEffect, type FC } from "react";
import { logger } from "matrix-js-sdk/lib/logger";

import { type RingingMediaViewModel } from "../state/media/RingingMediaViewModel";
import { useBehavior } from "../useBehavior";
import { useInitial } from "../useInitial";
import { prefetchSounds } from "../soundUtils";
import ringtoneMp3 from "../sound/ringtone.mp3?url";
import ringtoneOgg from "../sound/ringtone.ogg?url";
import { type UseAudioContext, useAudioContext } from "../useAudioContext";
import { useLatest } from "../useLatest";
import { useMediaDevices } from "../MediaDevicesContext";
import { useUrlParams } from "../UrlParams";

interface RingingAudioRendererProps {
  vm: RingingMediaViewModel | null;
  muted: boolean;
}

export const RingingAudioRenderer: FC<RingingAudioRendererProps> = ({
  vm,
  muted,
}) => {
  // Preload a waiting and decline sounds
  const sounds = useInitial(async () => {
    return prefetchSounds({
      ringtone: { mp3: ringtoneMp3, ogg: ringtoneOgg },
    });
  });
  const audio = useAudioContext({
    sounds,
    latencyHint: "interactive",
    muted,
  });

  return vm && <ActiveRingingAudioRenderer vm={vm} audio={audio} />;
};

interface ActiveRingingAudioRendererProps {
  vm: RingingMediaViewModel;
  audio: UseAudioContext<"ringtone"> | null;
}

const ActiveRingingAudioRenderer: FC<ActiveRingingAudioRendererProps> = ({
  vm,
  audio,
}) => {
  const audio_ = useLatest(audio);
  const pickupState = useBehavior(vm.pickupState$);
  const mediaDevices = useMediaDevices();
  const { callIntent } = useUrlParams();

  // While ringing, loop the ringtone
  useEffect((): void | (() => void) => {
    if (pickupState === "ringing" && audio_.current) {
      const endSound = audio_.current.playSoundLooping(
        "ringtone",
        audio_.current.soundDuration["ringtone"] ?? 1,
      );
      return () => {
        void endSound().catch((e) => {
          logger.error("Failed to stop ringing sound", e);
        });
      };
    }
  }, [pickupState, audio_]);

  // Ringing should be heard on the speaker, regardless of call type: it needs to be heard across
  // the room, not held up to the ear. Once picked up, hand control back to the normal per-call-type
  // default (earpiece for audio calls, speaker for video calls) that
  // AndroidControlledAudioOutput.chooseDefaultDeviceId already implements for the initial join —
  // our own explicit `select()` above overrides that same default, so we must explicitly restore
  // it here since a selection made via `select()` otherwise persists as the user's own preference.
  //
  // Neither override should ever touch a connected external device (Bluetooth, wired headset): if
  // the user is already on one, it was chosen either by their own explicit preference or by the
  // native layer's own priority ordering (which already ranks external devices above anything
  // built-in), and forcing it away to the built-in speaker/earpiece on ring start/end would be a
  // regression, not a default.
  useEffect(() => {
    if (pickupState !== "ringing") {
      return;
    }
    const isExternalDevice = (
      available: ReadonlyMap<string, { type: string }>,
      selectedId: string | undefined,
    ): boolean => {
      const label = selectedId && available.get(selectedId);
      return !!label && label.type !== "earpiece" && label.type !== "speaker";
    };

    const available = mediaDevices.audioOutput.available$.value;
    if (!isExternalDevice(available, mediaDevices.audioOutput.selected$.value?.id)) {
      const speaker = [...available].find(([, label]) => label.type === "speaker");
      if (speaker) {
        logger.info("Ringing: switching audio output to speaker");
        mediaDevices.audioOutput.select(speaker[0]);
      }
    }
    return () => {
      const availableNow = mediaDevices.audioOutput.available$.value;
      if (isExternalDevice(availableNow, mediaDevices.audioOutput.selected$.value?.id)) {
        return;
      }
      const wantedType = callIntent === "audio" ? "earpiece" : "speaker";
      const defaultDevice = [...availableNow].find(
        ([, label]) => label.type === wantedType,
      );
      if (defaultDevice) {
        logger.info(
          `Ringing ended: switching audio output back to the ${wantedType} default`,
        );
        mediaDevices.audioOutput.select(defaultDevice[0]);
      }
    };
  }, [pickupState, mediaDevices, callIntent]);

  return null;
};
